{
  "name": "build-clp-001-b",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "test": "npm run build && node --test tests/*.test.mjs"
  }
}

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { evaluateEligibility } from '../dist/src/index.js';

const here=path.dirname(fileURLToPath(import.meta.url));
const root=path.resolve(here,'..');
const a=path.resolve(root,'input/BUILD-CLP-001-A');
const sha256=b=>crypto.createHash('sha256').update(b).digest('hex');
const readJson=p=>JSON.parse(fs.readFileSync(p,'utf8'));

const manifest=readJson(path.join(a,'manifest.json'));
const bad=[];
for(const entry of manifest.files){
  const p=path.join(a,entry.path);
  const bytes=fs.readFileSync(p);
  if(sha256(bytes)!==entry.sha256) bad.push(entry.path);
}
if(bad.length) throw new Error(`A bundle manifest mismatch: ${bad.join(', ')}`);

const testText=fs.readFileSync(path.join(root,'tests/kernel.test.mjs'),'utf8');
const missing=[];
for(let i=1;i<=30;i++){
  const id=`AT-${String(i).padStart(3,'0')}`;
  if(!testText.includes(id)) missing.push(id);
}
for(let i=1;i<=7;i++){
  const id=`ADV-${String(i).padStart(3,'0')}`;
  if(!testText.includes(id)) missing.push(id);
}
if(missing.length) throw new Error(`Missing frozen test IDs: ${missing.join(', ')}`);

const workers=readJson(path.join(a,'fixtures/workers.json'));
for(const w of workers){
  const actual=evaluateEligibility(w).decision;
  if(actual!==w.expected_decision) throw new Error(`${w.worker_id}: expected ${w.expected_decision}, got ${actual}`);
}

const policy=readJson(path.join(a,'fixtures/transition-policy.json'));
if(policy.reject_unlisted_transitions!==true) throw new Error('transition policy does not fail closed');
if(policy.transitions.length!==24) throw new Error(`expected 24 frozen transitions, got ${policy.transitions.length}`);

console.log(JSON.stringify({
  status:'PASS',
  a_manifest_entries:manifest.files.length,
  frozen_test_ids:37,
  worker_fixtures:workers.map(w=>({worker_id:w.worker_id,decision:evaluateEligibility(w).decision})),
  transition_count:policy.transitions.length,
  reject_unlisted_transitions:true
},null,2));

import { createHash } from 'node:crypto';

export type CaseState = string;
export type DomainEvent = {
  event_id: string;
  event_type: string;
  aggregate_id: string;
  aggregate_version: number;
  correlation_id: string;
  causation_event_id: string | null;
  event_hash: string;
  source_refs?: string[];
  policy_refs?: string[];
  evidence_refs?: string[];
};

export type EvidenceArtifact = {
  evidence_id: string;
  evidence_class: string;
  evidence_type: string;
  content: unknown;
  parent_evidence_ids: string[];
  content_hash: string;
  created_at: string;
  verification_status: string;
};

export type WorkerFixture = {
  worker_id: string;
  employment_authorization: string;
  property_authorization: string;
  maintenance_role: string;
  capabilities: { basic_plumbing_maintenance: string };
  trainings: { fixture_repair_training: string };
  credentials_current: boolean;
  disciplinary_block: string;
  supervision_required: boolean;
  supervision_present: boolean;
  expected_decision: string;
};

function normalize(value: unknown): unknown {
  if (value === null || typeof value !== 'object') {
    if (typeof value === 'number' && !Number.isFinite(value)) throw new Error('non-finite numbers are not canonicalizable');
    return value;
  }
  if (Array.isArray(value)) return value.map(normalize);
  const out: Record<string, unknown> = {};
  for (const key of Object.keys(value as Record<string, unknown>).sort()) {
    const v = (value as Record<string, unknown>)[key];
    if (v !== undefined) out[key] = normalize(v);
  }
  return out;
}

export function canonicalize(value: unknown): string {
  return JSON.stringify(normalize(value));
}

export function hashCanonical(value: unknown): string {
  return 'sha256:' + createHash('sha256').update(canonicalize(value)).digest('hex');
}

export function initializeCase(caseId: string) {
  if (!caseId) throw new Error('case id required');
  return { case_id: caseId, state: 'REPORTED' as CaseState };
}

export function authorizeTransition(
  policy: any,
  from: string,
  to: string,
  eventType: string,
  satisfiedGuards: Set<string>
) {
  const candidate = policy.transitions.find((t: any) => t.from === from && t.to === to && t.event_type === eventType);
  if (!candidate) return { allowed: false, reason: 'UNLISTED_TRANSITION' };
  const missing = (candidate.guards ?? []).filter((g: string) => !satisfiedGuards.has(g));
  return missing.length === 0
    ? { allowed: true, transition_id: candidate.transition_id, missing_guards: [] }
    : { allowed: false, reason: 'GUARD_FAILED', transition_id: candidate.transition_id, missing_guards: missing };
}

export function verifyEventSequence(events: DomainEvent[]): true {
  const byAggregate = new Map<string, DomainEvent[]>();
  for (const e of events) {
    const list = byAggregate.get(e.aggregate_id) ?? [];
    list.push(e);
    byAggregate.set(e.aggregate_id, list);
  }
  for (const list of byAggregate.values()) {
    let prior = 0;
    for (const e of list) {
      if (e.aggregate_version !== prior + 1) throw new Error('aggregate versions must be monotonic +1');
      prior = e.aggregate_version;
    }
  }
  return true;
}

export function appendEvidence(
  ledger: EvidenceArtifact[],
  input: { evidence_id: string; evidence_class: string; evidence_type: string; content: unknown; parent_evidence_ids: string[] }
): EvidenceArtifact {
  if (ledger.some(x => x.evidence_id === input.evidence_id)) throw new Error('evidence id already exists');
  if (input.evidence_class === 'E1' && input.parent_evidence_ids.length === 0) throw new Error('E1 derived evidence requires parent evidence');
  for (const parent of input.parent_evidence_ids) {
    if (!ledger.some(x => x.evidence_id === parent)) throw new Error(`missing parent evidence: ${parent}`);
  }
  const artifact: EvidenceArtifact = {
    ...input,
    created_at: new Date(0).toISOString(),
    verification_status: 'UNVERIFIED',
    content_hash: hashCanonical({
      evidence_id: input.evidence_id,
      evidence_class: input.evidence_class,
      evidence_type: input.evidence_type,
      content: input.content,
      parent_evidence_ids: input.parent_evidence_ids
    })
  };
  ledger.push(Object.freeze(artifact));
  return artifact;
}

export function verifyArtifactHash(e: EvidenceArtifact): boolean {
  const expected = hashCanonical({
    evidence_id: e.evidence_id,
    evidence_class: e.evidence_class,
    evidence_type: e.evidence_type,
    content: e.content,
    parent_evidence_ids: e.parent_evidence_ids
  });
  return expected === e.content_hash;
}

export function deleteEvidence(_ledger: EvidenceArtifact[], _id: string): never {
  throw new Error('evidence ledger is append-only; destructive deletion prohibited');
}

const requiredAuthorityFields = [
  'source_id','source_class','jurisdiction','version','effective_from','effective_until',
  'retrieved_at','content_hash','official_source','verification_status'
];

export function validateAuthorityProvenance(source: Record<string, unknown>) {
  const missing = requiredAuthorityFields.filter(k => !(k in source));
  const hashOk = typeof source.content_hash === 'string' && /^sha256:[0-9a-f]{64}$/.test(source.content_hash);
  return { valid: missing.length === 0 && hashOk, missing, hash_ok: hashOk };
}

export function resolveApplicability(source: any, targetJurisdiction: string) {
  if (source.status === 'SUPERSEDED') return { status: 'SUPERSEDED' };
  if (source.conditional === true) return { status: 'POTENTIALLY_APPLICABLE' };
  if (source.jurisdiction === 'US-FEDERAL') return { status: 'POTENTIALLY_APPLICABLE' };
  if (targetJurisdiction === source.jurisdiction || targetJurisdiction.startsWith(source.jurisdiction + '-')) {
    return { status: 'APPLICABLE' };
  }
  return { status: 'NOT_APPLICABLE' };
}

export function validateRightsAnswer(answer: any, knownSourceIds: Set<string>) {
  const allowed = new Set(['A0','A1','A2','A3']);
  const errors: string[] = [];
  if (!allowed.has(answer.answer_class)) errors.push('answer class not allowed');
  if (answer.legal_liability_finding) errors.push('autonomous legal liability finding prohibited');
  for (const claim of answer.claims ?? []) {
    if (!Array.isArray(claim.source_ids) || claim.source_ids.length === 0) errors.push('uncited consequential claim');
    for (const id of claim.source_ids ?? []) if (!knownSourceIds.has(id)) errors.push(`unknown citation ${id}`);
  }
  return { valid: errors.length === 0, errors };
}

export function createWorkOrder(input: { work_order_id: string; resident_issue_id: string; authority_refs: string[] }) {
  if (!input.resident_issue_id || !input.authority_refs?.length) throw new Error('work order provenance required');
  return { ...input };
}

export function evaluateEligibility(worker: WorkerFixture, _context?: { aiRecommendation?: string }) {
  const predicate_results = {
    EMPLOYMENT_AUTHORIZED: worker.employment_authorization === 'ACTIVE',
    PROPERTY_AUTHORIZED: worker.property_authorization === 'ACTIVE',
    TASK_CAPABILITY_VERIFIED: worker.capabilities.basic_plumbing_maintenance === 'VERIFIED',
    REQUIRED_TRAINING_CURRENT: worker.trainings.fixture_repair_training === 'CURRENT',
    CREDENTIALS_CURRENT: worker.credentials_current === true,
    NO_TASK_RESTRICTION: worker.disciplinary_block === 'NONE',
    NO_REQUIRED_SUPERVISION_MISSING: !worker.supervision_required || worker.supervision_present
  };
  let decision = 'ELIGIBLE';
  if (!predicate_results.EMPLOYMENT_AUTHORIZED || !predicate_results.PROPERTY_AUTHORIZED) decision = 'INELIGIBLE_AUTHORIZATION';
  else if (!predicate_results.TASK_CAPABILITY_VERIFIED || !predicate_results.REQUIRED_TRAINING_CURRENT || !predicate_results.CREDENTIALS_CURRENT) decision = 'INELIGIBLE_CAPABILITY';
  else if (!predicate_results.NO_TASK_RESTRICTION || !predicate_results.NO_REQUIRED_SUPERVISION_MISSING) decision = 'INELIGIBLE_AUTHORIZATION';
  return { worker_id: worker.worker_id, decision, predicate_results, decision_hash: hashCanonical({worker_id: worker.worker_id, decision, predicate_results}) };
}

export function assertCredentialIntegrity(record: { worker_id: string; credentials_current: boolean; content_hash: string }) {
  return record.content_hash === hashCanonical({worker_id: record.worker_id, credentials_current: record.credentials_current});
}

export function validateTaskPack(pack: { status: string; approval_status: string; payload: unknown; task_pack_hash: string }) {
  const hashMatches = pack.task_pack_hash === hashCanonical(pack.payload);
  return { valid: pack.status === 'ACTIVE' && pack.approval_status === 'APPROVED' && hashMatches, hashMatches };
}

export function validateTaskPackExecutionVersion(x: { assignedVersion: string; assignedHash: string; executedVersion: string; executedHash: string }) {
  return x.assignedVersion === x.executedVersion && x.assignedHash === x.executedHash;
}

export function detectStopCondition(facts: Record<string, boolean>): string | null {
  if (facts.sewage_backup || facts.contaminated_discharge || facts.sanitary_overflow) return 'STOP-SEWAGE';
  if (facts.failed_shutoff || facts.uncontrolled_water_supply || facts.concealed_supply_leak) return 'STOP-SUPPLY';
  if (facts.soft_flooring || facts.subfloor_damage || facts.unstable_fixture || facts.structural_deterioration) return 'STOP-STRUCTURAL';
  if (facts.water_threatens_electrical) return 'STOP-ELECTRICAL';
  if (facts.outside_scope) return 'STOP-SCOPE';
  if (facts.credential_invalid) return 'STOP-CREDENTIAL';
  if (facts.procedure_unresolved) return 'STOP-PROCEDURE';
  if (facts.evidence_unobtainable) return 'STOP-EVIDENCE';
  return null;
}

export function submitCompletion(x: { completeEvidence: boolean; noStopCondition: boolean }) {
  if (!x.completeEvidence) return { state: 'IN_PROGRESS', accepted: false };
  if (!x.noStopCondition) return { state: 'ESCALATED', accepted: false };
  return { state: 'AWAITING_VERIFICATION', accepted: true };
}

export function verifyRepair(x: { workerId: string; verifierId: string; checks: boolean[]; taskPackHashMatches: boolean }) {
  if (x.workerId === x.verifierId) return { result: 'REJECTED' };
  if (x.checks.length !== 8) return { result: 'INCONCLUSIVE' };
  if (!x.taskPackHashMatches) return { result: 'FAILED' };
  return { result: x.checks.every(Boolean) ? 'VERIFIED' : 'FAILED' };
}

export function issueWorkGraphReceipt(x: { events: DomainEvent[]; workerId: string; taskClass: string; licensed: boolean }) {
  if (!x.events.some(e => e.event_type === 'RepairVerified')) throw new Error('RepairVerified event required before WorkGraph issuance');
  const claims = ['VERIFIED_TASK', `TASK_CLASS:${x.taskClass}`];
  if (x.licensed) claims.push('LICENSED_PLUMBER');
  return { worker_id: x.workerId, task_class: x.taskClass, claims, receipt_hash: hashCanonical({worker_id:x.workerId, task_class:x.taskClass, claims}) };
}

export function portableWorkGraph(receipt: Record<string, unknown>) {
  const denied = new Set(['resident_name','resident_contact','unit_id','resident_statement','private_media']);
  return Object.fromEntries(Object.entries(receipt).filter(([k]) => !denied.has(k)));
}

export function validateLineage(nodes: Array<{id:string; parents:string[]}>) {
  const ids = new Set(nodes.map(n => n.id));
  const missing: string[] = [];
  for (const n of nodes) for (const p of n.parents) if (!ids.has(p)) missing.push(`${n.id}->${p}`);
  return { valid: missing.length === 0, missing };
}

export function replayCase(
  correlationId: string,
  store: { events: DomainEvent[]; evidence: Array<{evidence_id:string}>; versions: Record<string, any> }
) {
  const events = store.events.filter(e => e.correlation_id === correlationId);
  if (events.length === 0) throw new Error('correlation id not found');
  verifyEventSequence(events);
  const eventIds = new Set(events.map(e => e.event_id));
  for (const e of events) {
    if (e.causation_event_id && !eventIds.has(e.causation_event_id)) throw new Error(`missing causation event ${e.causation_event_id}`);
  }
  const refs = new Set<string>();
  for (const e of events) {
    for (const r of e.source_refs ?? []) refs.add(r);
    for (const r of e.policy_refs ?? []) refs.add(r);
  }
  const resolvedVersions: Record<string, any> = {};
  for (const r of refs) {
    if (!(r in store.versions)) throw new Error(`missing pinned version ${r}`);
    resolvedVersions[r] = store.versions[r];
  }
  const evidenceIds = new Set(store.evidence.map(e => e.evidence_id));
  for (const e of events) for (const r of e.evidence_refs ?? []) if (!evidenceIds.has(r)) throw new Error(`missing evidence ${r}`);
  return { correlation_id: correlationId, events, resolvedVersions };
}

declare module 'node:crypto' {
  export function createHash(algorithm: string): {
    update(data: string | Uint8Array): any;
    digest(encoding: 'hex'): string;
  };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {
  authorizeTransition, evaluateEligibility, initializeCase, appendEvidence,
  canonicalize, hashCanonical, validateAuthorityProvenance, resolveApplicability,
  validateRightsAnswer, createWorkOrder, validateTaskPack, detectStopCondition,
  submitCompletion, verifyRepair, issueWorkGraphReceipt, portableWorkGraph,
  verifyEventSequence, validateLineage, replayCase, verifyArtifactHash,
  assertCredentialIntegrity, validateTaskPackExecutionVersion, deleteEvidence
} from '../dist/src/index.js';
import workers from '../input/BUILD-CLP-001-A/fixtures/workers.json' with { type: 'json' };
import transitionPolicy from '../input/BUILD-CLP-001-A/fixtures/transition-policy.json' with { type: 'json' };

const workerA = workers[0];
const workerB = workers[1];
const workerC = workers[2];
const sha = 'sha256:' + 'a'.repeat(64);
const authority = (id, jurisdiction, status='CURRENT') => ({
  source_id:id, source_class:'SC-0', jurisdiction, version:'1.0.0',
  effective_from:'2026-01-01', effective_until:null, retrieved_at:'2026-10-03T22:00:00Z',
  content_hash:sha, official_source:true, verification_status:'VERIFIED', status
});

// AT-001 / AT-023 / ADV-007
 test('AT-001 preserves original resident evidence independently from derived evidence', () => {
  const ledger = [];
  const e0 = appendEvidence(ledger, {evidence_id:'ev_e0', evidence_class:'E0', evidence_type:'resident_statement', content:'toilet keeps running', parent_evidence_ids:[]});
  const e1 = appendEvidence(ledger, {evidence_id:'ev_e1', evidence_class:'E1', evidence_type:'classification', content:'TOILET_FILL_SYSTEM_FAULT', parent_evidence_ids:[e0.evidence_id]});
  assert.equal(ledger[0].content, 'toilet keeps running');
  assert.equal(e1.parent_evidence_ids[0], e0.evidence_id);
  assert.notEqual(e0.content_hash, e1.content_hash);
});
 test('AT-023 detects evidence mutation after hashing', () => {
  const ledger=[];
  const e = appendEvidence(ledger,{evidence_id:'ev_hash',evidence_class:'E0',evidence_type:'resident_statement',content:'original',parent_evidence_ids:[]});
  assert.equal(verifyArtifactHash(e), true);
  const forged = {...e, content:'changed'};
  assert.equal(verifyArtifactHash(forged), false);
});
 test('ADV-007 prevents destructive evidence deletion', () => {
  const ledger=[];
  appendEvidence(ledger,{evidence_id:'ev_keep',evidence_class:'E0',evidence_type:'resident_statement',content:'x',parent_evidence_ids:[]});
  assert.throws(() => deleteEvidence(ledger,'ev_keep'), /append-only/);
});

// AT-002 / AT-024 / AT-029 / AT-030
 test('AT-002 initializes case at REPORTED', () => assert.equal(initializeCase('CASE-1').state,'REPORTED'));
 test('AT-024 rejects non-monotonic aggregate versions', () => {
  const ev=(v)=>({event_id:`evt_${v}`,event_type:'ResidentIssueReported',aggregate_id:'CASE-1',aggregate_version:v,correlation_id:'corr_1',causation_event_id:null,event_hash:sha});
  assert.throws(()=>verifyEventSequence([ev(1),ev(3)]),/monotonic/);
});
 test('AT-029 forbids IN_PROGRESS -> WORKGRAPH_RECORDED', () => {
  const r=authorizeTransition(transitionPolicy,'IN_PROGRESS','WORKGRAPH_RECORDED','WorkGraphUpdated',new Set());
  assert.equal(r.allowed,false);
});
 test('AT-030 CLOSED -> REOPENED requires new recurrence evidence and does not rewrite history', () => {
  assert.equal(authorizeTransition(transitionPolicy,'CLOSED','REOPENED','CaseReopened',new Set(['new_recurrence_evidence_present'])).allowed,true);
  assert.equal(authorizeTransition(transitionPolicy,'CLOSED','REOPENED','CaseReopened',new Set()).allowed,false);
});

// AT-003..AT-007 + ADV-001..003
 test('AT-003 authority provenance requires all frozen fields', () => {
  assert.equal(validateAuthorityProvenance(authority('AUTH-MN-504B161','US-MN')).valid,true);
  const broken=authority('bad','US-MN'); delete broken.content_hash;
  assert.equal(validateAuthorityProvenance(broken).valid,false);
});
 test('AT-004 resolves MN and Apple Valley applicable while HUD remains potentially applicable', () => {
  assert.equal(resolveApplicability(authority('AUTH-MN-504B161','US-MN'),'US-MN-DAKOTA-APPLE-VALLEY').status,'APPLICABLE');
  assert.equal(resolveApplicability(authority('AUTH-APPLEVALLEY-PLUMBING','US-MN-DAKOTA-APPLE-VALLEY'),'US-MN-DAKOTA-APPLE-VALLEY').status,'APPLICABLE');
  const hud={...authority('AUTH-HUD-NSPIRE','US-FEDERAL'),source_class:'SC-1',conditional:true};
  assert.equal(resolveApplicability(hud,'US-MN-DAKOTA-APPLE-VALLEY').status,'POTENTIALLY_APPLICABLE');
 });
 test('AT-005 retrieval is not applicability', () => {
  const wi=authority('WI','US-WI');
  assert.equal(resolveApplicability(wi,'US-MN-DAKOTA-APPLE-VALLEY').status,'NOT_APPLICABLE');
 });
 test('AT-006 rights answer requires allowed class and citations',()=>{
  assert.equal(validateRightsAnswer({answer_class:'A2',claims:[{text:'repair obligation',source_ids:['AUTH-MN-504B161']}],legal_liability_finding:false},new Set(['AUTH-MN-504B161'])).valid,true);
 });
 test('AT-007 blocks autonomous legal-liability findings',()=>{
  assert.equal(validateRightsAnswer({answer_class:'A2',claims:[{text:'illegal',source_ids:['AUTH-MN-504B161']}],legal_liability_finding:true},new Set(['AUTH-MN-504B161'])).valid,false);
 });
 test('ADV-001 rejects fabricated citations',()=>{
  assert.equal(validateRightsAnswer({answer_class:'A2',claims:[{text:'x',source_ids:['FAKE']}],legal_liability_finding:false},new Set(['AUTH-MN-504B161'])).valid,false);
 });
 test('ADV-002 rejects Wisconsin authority for Apple Valley',()=>assert.equal(resolveApplicability(authority('WI','US-WI'),'US-MN-DAKOTA-APPLE-VALLEY').status,'NOT_APPLICABLE'));
 test('ADV-003 superseded source cannot execute as current authority',()=>assert.equal(resolveApplicability(authority('OLD','US-MN','SUPERSEDED'),'US-MN-DAKOTA-APPLE-VALLEY').status,'SUPERSEDED'));

// AT-008..AT-012 + ADV-004
 test('AT-008 work order requires resident and authority provenance',()=>{
  assert.throws(()=>createWorkOrder({work_order_id:'WO-1',resident_issue_id:'',authority_refs:[]}),/provenance/);
  assert.equal(createWorkOrder({work_order_id:'WO-1',resident_issue_id:'ISSUE-1',authority_refs:['AUTH-MN-504B161']}).work_order_id,'WO-1');
 });
 test('AT-009 WORKER-A is eligible',()=>assert.equal(evaluateEligibility(workerA).decision,'ELIGIBLE'));
 test('AT-010 WORKER-B is ineligible by capability',()=>assert.equal(evaluateEligibility(workerB).decision,'INELIGIBLE_CAPABILITY'));
 test('AT-011 WORKER-C is ineligible by authorization',()=>assert.equal(evaluateEligibility(workerC).decision,'INELIGIBLE_AUTHORIZATION'));
 test('AT-012 AI recommendation cannot override deterministic eligibility',()=>{
  assert.equal(evaluateEligibility(workerB,{aiRecommendation:'ELIGIBLE'}).decision,'INELIGIBLE_CAPABILITY');
 });
 test('ADV-004 credential integrity fails after fixture mutation',()=>{
  const signed={worker_id:'WORKER-A',credentials_current:true,content_hash:''};
  signed.content_hash=hashCanonical({worker_id:signed.worker_id,credentials_current:signed.credentials_current});
  assert.equal(assertCredentialIntegrity(signed),true);
  assert.equal(assertCredentialIntegrity({...signed,credentials_current:false}),false);
 });

// AT-013..AT-019 + ADV-005/006
 test('AT-013 only approved active task pack with matching hash executes',()=>{
  const pack={status:'ACTIVE',approval_status:'APPROVED',payload:{scope:'fill-valve'},task_pack_hash:''};
  pack.task_pack_hash=hashCanonical(pack.payload);
  assert.equal(validateTaskPack(pack).valid,true);
  assert.equal(validateTaskPack({...pack,task_pack_hash:sha}).valid,false);
 });
 test('AT-014 structural finding triggers STOP-STRUCTURAL escalation',()=>assert.equal(detectStopCondition({soft_flooring:true}),'STOP-STRUCTURAL'));
 test('AT-015 sewage finding triggers STOP-SEWAGE',()=>assert.equal(detectStopCondition({sewage_backup:true}),'STOP-SEWAGE'));
 test('AT-016 completion enters AWAITING_VERIFICATION, never VERIFIED',()=>assert.equal(submitCompletion({completeEvidence:true,noStopCondition:true}).state,'AWAITING_VERIFICATION'));
 test('AT-017 independent verifier is required',()=>assert.equal(verifyRepair({workerId:'W1',verifierId:'SUP1',checks:Array(8).fill(true),taskPackHashMatches:true}).result,'VERIFIED'));
 test('AT-018 continuing-running verification failure blocks verification',()=>assert.equal(verifyRepair({workerId:'W1',verifierId:'SUP1',checks:[true,true,false,true,true,true,true,true],taskPackHashMatches:true}).result,'FAILED'));
 test('AT-019 all V1-V8 checks pass as VERIFIED',()=>assert.equal(verifyRepair({workerId:'W1',verifierId:'SUP1',checks:Array(8).fill(true),taskPackHashMatches:true}).result,'VERIFIED'));
 test('ADV-005 stale task pack version/hash is rejected',()=>assert.equal(validateTaskPackExecutionVersion({assignedVersion:'1',assignedHash:sha,executedVersion:'2',executedHash:sha}),false));
 test('ADV-006 worker self-verification is rejected',()=>assert.equal(verifyRepair({workerId:'W1',verifierId:'W1',checks:Array(8).fill(true),taskPackHashMatches:true}).result,'REJECTED'));

// AT-020..AT-022
 test('AT-020 WorkGraph requires preceding RepairVerified event',()=>{
  assert.throws(()=>issueWorkGraphReceipt({events:[],workerId:'WORKER-A',taskClass:'TOILET_FILL_VALVE_FAILURE',licensed:false}),/RepairVerified/);
  const e={event_id:'evt_verified',event_type:'RepairVerified',aggregate_id:'CASE-1',aggregate_version:1,correlation_id:'corr_1',causation_event_id:null,event_hash:sha};
  assert.equal(issueWorkGraphReceipt({events:[e],workerId:'WORKER-A',taskClass:'TOILET_FILL_VALVE_FAILURE',licensed:false}).worker_id,'WORKER-A');
 });
 test('AT-021 WorkGraph does not fabricate licensure',()=>{
  const e={event_id:'evt_verified',event_type:'RepairVerified',aggregate_id:'CASE-1',aggregate_version:1,correlation_id:'corr_1',causation_event_id:null,event_hash:sha};
  assert.equal(issueWorkGraphReceipt({events:[e],workerId:'WORKER-A',taskClass:'TOILET_FILL_VALVE_FAILURE',licensed:false}).claims.includes('LICENSED_PLUMBER'),false);
 });
 test('AT-022 portable receipt strips resident-identifying data',()=>{
  const out=portableWorkGraph({worker_id:'WORKER-A',resident_name:'Resident X',unit_id:'UNIT-1',private_media:['x'],claims:['VERIFIED_TASK']});
  assert.equal('resident_name' in out,false); assert.equal('unit_id' in out,false); assert.equal('private_media' in out,false);
 });

