 test('AT-026 replay reconstructs case solely by correlation id',()=>{
  const events=[
   {event_id:'evt_1',event_type:'ResidentIssueReported',aggregate_id:'CASE-1',aggregate_version:1,correlation_id:'corr_case',causation_event_id:null,event_hash:sha,source_refs:['AUTH@1'],policy_refs:['POL@1'],evidence_refs:['ev_1']},
   {event_id:'evt_2',event_type:'CaseClosed',aggregate_id:'CASE-1',aggregate_version:2,correlation_id:'corr_case',causation_event_id:'evt_1',event_hash:sha,source_refs:['AUTH@1'],policy_refs:['POL@1'],evidence_refs:['ev_2']}
  ];
  const r=replayCase('corr_case',{events,evidence:[{evidence_id:'ev_1'},{evidence_id:'ev_2'}],versions:{'AUTH@1':{v:1},'POL@1':{v:1}}});
  assert.equal(r.events.length,2); assert.deepEqual(r.resolvedVersions['AUTH@1'],{v:1});
 });
 test('AT-027 historical replay pins original versions after new versions exist',()=>{
  const events=[{event_id:'evt_1',event_type:'ResidentIssueReported',aggregate_id:'CASE-1',aggregate_version:1,correlation_id:'corr_hist',causation_event_id:null,event_hash:sha,source_refs:['AUTH@1'],policy_refs:[],evidence_refs:[]}];
  const r=replayCase('corr_hist',{events,evidence:[],versions:{'AUTH@1':{v:1},'AUTH@2':{v:2}}});
  assert.equal(r.resolvedVersions['AUTH@1'].v,1); assert.equal('AUTH@2' in r.resolvedVersions,false);
 });
 test('AT-028 current-versus-historical resolution remains separate',()=>{
  const historical={'AUTH@1':{v:1}}, current={'AUTH@2':{v:2}};
  assert.notDeepEqual(historical,current);
 });
